const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const rawWhen = typeof $json.when === 'string' ? $json.when.trim().toLowerCase() : '';
const rawFilter = typeof $json.filter === 'string' ? $json.filter.trim().toLowerCase() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'The report request needs a valid conversation and request ID.' };
}
const when = ['latest', 'week'].includes(rawWhen) ? rawWhen : 'latest';
const filter = ['open', 'closing', 'all'].includes(rawFilter) ? rawFilter : 'open';
const proposedInput = { sessionId, requestId, when, filter };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Report Input').first().json;
const runRows = $('Read Latest Run').all().map((item) => item.json).filter((row) => row && row.ranAt);
const rows = $input.all().map((item) => item.json).filter((row) => row && row.fingerprint);

if (runRows.length === 0) {
  return [{ json: { ...input, response: {
    ok: true,
    hasRun: false,
    message: 'No funding scan has finished yet. Tell the user you can go and look now if they would like, which takes a few minutes.'
  } } }];
}

const latest = runRows[0];
const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
// Reading this table cannot tell a run that is working from one that died:
// both leave the same row behind. Past DEAD_AFTER, "still running" would be a
// confident lie, so it says what it actually knows and offers a way out.
// Kept in step with Decide Run in 68, which will start a fresh scan over a run
// this old. Reading them differently meant that for ten minutes in the middle
// a new search would start while this tool still insisted one was in progress.
// Both windows have to outlast a real scan or they call a working search dead.
// A measured run took eighteen minutes, and 71 gives itself thirty before n8n
// stops it, so thirty-two is the first age at which "it did not survive" is a
// fact rather than a guess. SLOW_AFTER is early on purpose: long before that,
// the owner is told it is taking a while and that they can have a fresh one.
const DEAD_AFTER = 32;
const SLOW_AFTER = 8;

if (String(latest.status ?? '') === 'running') {
  const age = minutesSince(latest.ranAt);
  if (age !== null && age >= DEAD_AFTER) {
    return [{ json: { ...input, response: {
      ok: true,
      hasRun: false,
      interrupted: true,
      startedAt: latest.ranAt,
      startedMinutesAgo: age,
      message: `A search started ${age} minutes ago and never reported back, so it did not survive — usually the agent restarted while it was working. Nothing was saved from it. Tell the user that plainly, and offer to run a fresh one now.`
    } } }];
  }
  const waited = age === null ? 'a few minutes' : `${age} minute(s)`;
  return [{ json: { ...input, response: {
    ok: true,
    hasRun: false,
    running: true,
    startedAt: latest.ranAt,
    startedMinutesAgo: age,
    message: age !== null && age >= SLOW_AFTER
      ? `A search has been running for ${waited}, which is longer than one usually takes. Tell the user it may still land, and that if it has not reported back in a few more minutes they should ask you to search again anyway.`
      : `A funding search started ${waited} ago and is still running. Tell the user how long it has been going and to ask again shortly. Do not start another one.`
  } } }];
}
const dayIndex = (value) => {
  const text = String(value ?? '').trim();
  const isoDate = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoDate) return Math.floor(Date.UTC(Number(isoDate[1]), Number(isoDate[2]) - 1, Number(isoDate[3])) / 86400000);
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  return Math.floor(Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate()) / 86400000);
};
const todayIndex = dayIndex(new Date());
const daysUntil = (value) => {
  if (!value) return null;
  const index = dayIndex(value);
  return index === null ? null : index - todayIndex;
};

const live = rows.filter((row) => String(row.dismissed ?? '') !== 'yes');
const chosen = live.filter((row) => {
  if (input.filter === 'all') return true;
  const left = daysUntil(row.closesAt);
  if (input.filter === 'closing') return left !== null && left >= 0 && left <= 14;
  return String(row.status ?? '') !== 'closed' && (left === null || left >= 0);
});

chosen.sort((a, b) => {
  const leftA = daysUntil(a.closesAt);
  const leftB = daysUntil(b.closesAt);
  if (leftA === null && leftB === null) return 0;
  if (leftA === null) return 1;
  if (leftB === null) return -1;
  return leftA - leftB;
});

const opportunities = chosen.slice(0, 25).map((row) => ({
  programName: row.programName,
  administeredBy: row.administeredBy,
  amountText: row.amountText,
  closesAt: row.closesAt,
  daysLeft: daysUntil(row.closesAt),
  status: row.status,
  verdict: row.verdict,
  verdictReason: row.verdictReason,
  deciderCriterion: row.deciderCriterion,
  sourceTrust: row.sourceTrust,
  officialUrl: row.officialUrl,
}));

// The agent cannot see inside a scan, so when a report comes back empty it
// fills the silence with a guess. Last time it told the owner their business
// profile was probably too thin — wrong, and the one explanation guaranteed to
// leave them feeling at fault for a fault on this side. Hand it the numbers.
const searchCount = Number(latest.searchCount ?? 0);
const foundNothing = opportunities.length === 0 && live.length === 0;

return [{ json: { ...input, response: {
  ok: true,
  hasRun: true,
  ranAt: latest.ranAt,
  runStatus: latest.status,
  reportText: String(latest.reportText ?? ''),
  totalTracked: live.length,
  count: opportunities.length,
  filter: input.filter,
  searchCount,
  errorSummary: String(latest.errorSummary ?? ''),
  opportunities,
  message: foundNothing
    ? 'This is the report from the last finished search, and it found nothing. Read the report back as it is written. Do not invent a reason for the empty result, and never suggest the business profile is missing details: a search only runs once a profile is saved, so that is never the cause. If searchCount is 0 the search never reached the web at all, which is a fault on this side and nothing the user did or needs to fix. Offer to search again.'
    : 'This is the report from the last finished search. Nothing was researched to answer this question.'
} } }];

const input = $('Validate Report Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'get_funding_report',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
